#!/bin/bash
# Print the 3 most frequent IP addresses from access.log,
# one per line, most frequent first; ties broken by first appearance.
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first_seen)) {
        first_seen[ip] = NR
        order[++n] = ip
    }
}
END {
    # Build a sortable key: zero-padded descending count, then first appearance
    for (i = 1; i <= n; i++) {
        ip = order[i]
        printf "%010d %010d %s\n", 9999999999 - count[ip], first_seen[ip], ip
    }
}
' access.log | sort | head -n 3 | awk '{print $3}'
